<?php
require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/helpers.php'; require_role(['Supervisor','HR Admin','Admin']); $pdo=db(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$id=(int)($_POST['id']??0);$action=$_POST['decision']??'';if(!in_array($action,['Approved','Rejected'],true)){ $error='Choose approve or reject.';}else{ $st=$pdo->prepare("UPDATE leave_requests SET status=?, approved_by=?, approved_at=NOW() WHERE id=? AND status='Pending'");$st->execute([$action,current_user()['id'],$id]);redirect($_SERVER['PHP_SELF'].'?updated=1');}}
$title='Leave Agree';$rows=$pdo->query("SELECT l.*,e.employee_code,e.full_name,e.department FROM leave_requests l JOIN employees e ON e.id=l.employee_id ORDER BY (l.status='Pending') DESC,l.id DESC")->fetchAll();require __DIR__.'/../includes/header.php';?>
<div class="page-head"><div><h2>Leave Agree</h2><p>Review pending leave requests from employees.</p></div></div><?php if(isset($_GET['updated'])):?><div class="card"><p>Leave decision saved.</p></div><?php endif;?><?php if($error):?><div class="card"><p><?=e($error)?></p></div><?php endif;?><div class="card"><h3>Leave requests (<?=count($rows)?>)</h3><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Department</th><th>Leave type</th><th>Dates</th><th>Days</th><th>Reason</th><th>Status / action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7">No leave requests found.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['employee_code'].' — '.$r['full_name'])?></td><td><?=e($r['department'])?></td><td><?=e($r['leave_type'])?></td><td><?=e($r['start_date'].' to '.$r['end_date'])?></td><td><?=(int)$r['days']?></td><td><?=e($r['reason']??'')?></td><td><?=e($r['status'])?><?php if($r['status']==='Pending'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button name="decision" value="Approved">Agree / Approve</button> <button name="decision" value="Rejected">Reject</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>